data.default.conf:
server {
    listen 8080;
    server_name _;
    root /usr/share/nginx/html;
    index index.html;
    server_tokens off;
    # Preserve the browser's public HTTPS origin behind Cloudflare/ingress.
    absolute_redirect off;
    charset utf-8;
    gzip on;
    gzip_types text/css application/javascript application/json image/svg+xml;
    include /etc/nginx/security-headers.conf;
    location = /bio { return 301 /links; }
    location = "/ZERO38 Booking.dc.html" { return 301 /$is_args$args; }
    location = "/HitLa-Z38tt.dc.html" { return 301 /admin$is_args$args; }
    location = "/Admin.dc.html" { return 301 /admin$is_args$args; }
    location = "/Messages.dc.html" { return 301 /messages$is_args$args; }
    location = "/Consent Form.dc.html" { return 301 /consent$is_args$args; }
    location = "/Links.dc.html" { return 301 /links$is_args$args; }
    location = /admin {
        include /etc/nginx/security-headers.conf;
        add_header X-Robots-Tag "noindex, nofollow" always;
        add_header Cache-Control "no-store" always;
        try_files /index.html =404;
    }
    location = /messages {
        include /etc/nginx/security-headers.conf;
        add_header X-Robots-Tag "noindex, nofollow" always;
        add_header Cache-Control "no-store" always;
        try_files /index.html =404;
    }
    location = /consent {
        include /etc/nginx/security-headers.conf;
        add_header X-Robots-Tag "noindex, nofollow" always;
        add_header Cache-Control "no-store" always;
        try_files /index.html =404;
    }
    location ~ ^/(api(?:/|$)|\.netlify/functions/) {
        default_type application/json;
        add_header Cache-Control "no-store" always;
        return 503 '{"error":"Booking services are not configured yet. Please contact @zero38tattoos."}';
    }
    location /assets/ { try_files $uri =404; expires 1d; }
    location / { try_files $uri $uri/ /index.html; }
}

data.security-headers.conf:
add_header X-Content-Type-Options "nosniff" always;
add_header X-Frame-Options "DENY" always;
add_header Referrer-Policy "strict-origin-when-cross-origin" always;
add_header Permissions-Policy "camera=(), microphone=(), geolocation=()" always;
add_header Content-Security-Policy "default-src 'self'; script-src 'self' https://www.youtube.com https://s.ytimg.com; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com; img-src 'self' data: https:; connect-src 'self'; frame-src https://www.youtube.com https://www.youtube-nocookie.com; frame-ancestors 'none'; object-src 'none'; base-uri 'self'; form-action 'self'" always;
